import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Clock Picker","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/clock-picker.md","filePath":"documentation/field-types/clock-picker.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/clock-picker.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="clock-picker" tabindex="-1">Clock Picker <a class="header-anchor" href="#clock-picker" aria-label="Permalink to “Clock Picker”">​</a></h1><p>The <code>Clock Picker</code> is a specialized field type to select time in analog or interactive clock picker components. This guide details the configuration options available to customize the Clock Picker field type according to your requirements.</p><img src="/image/clock-picker-01.png" alt="Clock Picker Configuration"><h2 id="field-options" tabindex="-1">Field Options <a class="header-anchor" href="#field-options" aria-label="Permalink to “Field Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Clock Time Format</strong></td><td>Specifies the format for displaying the selected time.</td><td><code>hh:mm:ss A</code> for a 12-hour format with AM/PM display.</td></tr><tr><td><strong><a href="#clock-picker-library-name">Clock Picker Library Name</a></strong></td><td>Selects the time selection library or component used for the Clock Picker field.</td><td>Choose from predefined libraries or <code>&quot;Other&quot;</code> for custom configurations.</td></tr><tr><td><strong>Clock Hand Selector Address</strong></td><td>CSS selector identifying the clock hand element used for selecting time components in custom clock implementations.</td><td><code>.clock-hand</code>, <code>.MuiClockPointer-thumb</code></td></tr><tr><td><strong>Clock Meridiem List Selector Address</strong></td><td>CSS selector for the element managing <code>AM/PM</code> selection in the Clock Picker field.</td><td><code>.meridiem-toggle</code>, <code>[data-am-pm]</code></td></tr><tr><td><strong>Active Clock Components</strong></td><td>Defines the components <code>(hours, minutes, seconds, meridiem)</code> that are enabled in the Clock Picker field.</td><td>Select <code>hours</code>, <code>minutes</code>, <code>meridiem</code> and <code>seconds</code>.</td></tr><tr><td><strong>Address of the button to open the clock</strong></td><td>CSS selector for the button that triggers the clock interface for selecting time.</td><td><code>#openTimePicker</code>, <code>.clock-trigger</code></td></tr><tr><td><strong>Enter Timer Submit Button Selector Address</strong></td><td>CSS selector for the submit button used to confirm the selected time in the Clock Picker field.</td><td><code>.clock-submit</code>, <code>button.confirm-time</code></td></tr></tbody></table><h2 id="additional-options" tabindex="-1">Additional Options <a class="header-anchor" href="#additional-options" aria-label="Permalink to “Additional Options”">​</a></h2><ul><li><strong>Enable Button to Open Clock:</strong> Activates the specified button to open the clock interface.</li><li><strong>Submit Button After Time Selection:</strong> Automatically submits the selected time into the form when enabled.</li></ul><h2 id="clock-picker-library-name" tabindex="-1">Clock Picker Library Name <a class="header-anchor" href="#clock-picker-library-name" aria-label="Permalink to “Clock Picker Library Name”">​</a></h2><ul><li>MUI-V4 Time Picker</li><li>MUI-X Time Picker (React)</li><li>Other (Custom)</li></ul><h2 id="examples-of-clock-picker-libraries" tabindex="-1">Examples of Clock Picker Libraries <a class="header-anchor" href="#examples-of-clock-picker-libraries" aria-label="Permalink to “Examples of Clock Picker Libraries”">​</a></h2><ul><li><a href="https://mui.com/x/react-date-pickers/" target="_blank" rel="noreferrer">MUI-X React Time Pickers</a></li><li><a href="https://mui.com/x/react-date-pickers/time-picker/#available-components" target="_blank" rel="noreferrer">MUI-X Time Picker Available Components</a></li><li><a href="https://v5-0-6.mui.com/components/time-picker/" target="_blank" rel="noreferrer">MUI v5 Time Picker Component</a></li><li><a href="https://weareoutman.github.io/clockpicker/" target="_blank" rel="noreferrer">ClockPicker on GitHub</a></li><li><a href="https://buefy.org/documentation/clockpicker/" target="_blank" rel="noreferrer">Buefy Clockpicker</a></li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field-types.html">Field Types</a> — Learn about different field types</li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-response-action.html">Field Response Actions</a> — Configure response behaviors</li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template</a> — Prepare Excel (.xlsx) templates</li><li><img src="/svg/browser.svg" class="doc-icon"> <a href="/documentation/site/site-settings.html">Site Settings</a> — Configure site-wide automation settings</li></ul>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};